#!/bin/bash
export AGENT_BROWSER_SESSION=nl-qa
ab() { agent-browser "$@"; }
ab eval '(async()=>{ await Promise.all(["/js/app.js","/js/lib/providers.js"].map(u=>fetch(u,{cache:"reload"}))); location.reload(); return 1 })()' >/dev/null; sleep 2
echo "--- new empty project: book/export empty states"; ab eval '(async()=>{ window.prompt=()=>"ว่าง"; document.querySelector("#tabs [data-view=home]").click(); await new Promise(r=>setTimeout(r,200)); document.querySelector("[data-action=new-project]").click(); await new Promise(r=>setTimeout(r,400)); const o={}; for (const v of ["book","export","settings"]) { document.querySelector(`#tabs [data-view=${v}]`).click(); await new Promise(r=>setTimeout(r,250)); o[v]=document.querySelector("main").innerText.slice(0,70).replace(/\n/g," | "); } o.exportDisabled=[...document.querySelectorAll("main [data-kind]")].every(b=>b.disabled); return o })()'
echo "--- paste import"; ab eval '(async()=>{ document.querySelector("#tabs [data-view=chapters]").click(); await new Promise(r=>setTimeout(r,250)); const t=document.querySelector("#pasteIn"); t.value="Chapter 1\nHello Tom.\n\nChapter 2\nTom left.\n\nChapter 3\nThe end."; document.querySelector("[data-action=paste-import]").click(); await new Promise(r=>setTimeout(r,400)); const msg=document.querySelector(".issues")?.innerText.split("\n")[0]; document.querySelector("[data-action=confirm-import]").click(); await new Promise(r=>setTimeout(r,400)); return {msg, rows:document.querySelectorAll("tbody tr").length} })()'
echo "--- settings save"; ab eval '(async()=>{ document.querySelector("#tabs [data-view=settings]").click(); await new Promise(r=>setTimeout(r,250)); const n=document.querySelector("[name=name]"); n.value="ว่าง (แก้ชื่อ)"; n.dispatchEvent(new Event("change",{bubbles:true})); await new Promise(r=>setTimeout(r,300)); return {header:document.querySelector("#topProject").innerText, adv:!!document.querySelector("details [name=chunkSize]")} })()'
echo "--- translate 3 + book"; ab eval '(async()=>{ document.querySelector("#tabs [data-view=chapters]").click(); await new Promise(r=>setTimeout(r,250)); document.querySelector("[data-action=translate-todo]").click(); for(let i=0;i<40;i++){ await new Promise(r=>setTimeout(r,300)); if(/แปลเสร็จ/.test(document.querySelector("#runner").innerText)) break;} document.querySelector("#runner [data-action=read-book]").click(); await new Promise(r=>setTimeout(r,300)); return {sel:[...document.querySelectorAll("#chapterSel option")].map(o=>o.innerText), first:document.querySelector(".book-kicker").innerText} })()'
echo "--- delete chapter + delete project"; ab eval '(async()=>{ window.confirm=()=>true; document.querySelector("#tabs [data-view=chapters]").click(); await new Promise(r=>setTimeout(r,250)); document.querySelector("[data-action=delete-chapter]").click(); await new Promise(r=>setTimeout(r,250)); const rows=document.querySelectorAll("tbody tr").length; document.querySelector("#tabs [data-view=home]").click(); await new Promise(r=>setTimeout(r,250)); const before=document.querySelectorAll(".projects li").length; [...document.querySelectorAll("[data-action=delete-project]")].find(b=>b.closest("li").innerText.includes("แก้ชื่อ")).click(); await new Promise(r=>setTimeout(r,400)); return {rowsAfterDel:rows, projects:[before, document.querySelectorAll(".projects li").length], disabledTabs:[...document.querySelectorAll("#tabs button")].filter(b=>b.disabled).length} })()'
echo "--- back after delete"; ab back >/dev/null; sleep 0.5; ab eval '({hash:location.hash, main:document.querySelector("main").innerText.slice(0,50)})'
echo "--- errors"; ab errors
